import React from 'react';
import {
  AbsoluteFill,
  Audio,
  Img,
  Sequence,
  interpolate,
  staticFile,
  useCurrentFrame,
} from 'remotion';
import {Particles} from '../Particles';
import {Subtitle} from '../Subtitle';

// 场景 1 · Hook：虚拟人从光晕中清晰浮现，挥手问好
export const Scene1Hero: React.FC = () => {
  const frame = useCurrentFrame();
  const DURATION = 96;

  const blur = interpolate(frame, [0, 22], [26, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const scale = interpolate(frame, [0, DURATION], [1.04, 1.12]);
  const fadeOut = interpolate(frame, [DURATION - 8, DURATION], [1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  return (
    <AbsoluteFill style={{opacity: fadeOut}}>
      {/* 背景光晕 */}
      <AbsoluteFill
        style={{
          background:
            'radial-gradient(120% 90% at 50% 30%, #3A2A55 0%, #241B33 55%, #171226 100%)',
        }}
      />
      <AbsoluteFill
        style={{
          background:
            'radial-gradient(45% 40% at 68% 30%, rgba(255,143,163,0.22) 0%, transparent 70%)',
        }}
      />
      <AbsoluteFill
        style={{
          background:
            'radial-gradient(50% 45% at 28% 75%, rgba(126,200,227,0.18) 0%, transparent 70%)',
        }}
      />

      {/* 虚拟人：由虚到实 + 缓慢推近 */}
      <AbsoluteFill
        style={{
          filter: `blur(${blur}px)`,
          transform: `scale(${scale})`,
        }}
      >
        <Img
          src={staticFile('hero_wave.png')}
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
          }}
        />
      </AbsoluteFill>

      {/* 暗角与顶部压暗，保证字幕可读 */}
      <AbsoluteFill
        style={{
          background:
            'linear-gradient(180deg, rgba(10,8,20,0.35) 0%, transparent 30%, transparent 62%, rgba(10,8,20,0.5) 100%)',
        }}
      />

      <Particles count={30} seed={11} opacityScale={0.9} />

      {/* 左上角主题标签 */}
      <div
        style={{
          position: 'absolute',
          top: 64,
          left: 80,
          display: 'flex',
          alignItems: 'center',
          gap: 16,
          opacity: interpolate(frame, [10, 30], [0, 1], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          }),
        }}
      >
        <div
          style={{
            width: 44,
            height: 3,
            borderRadius: 2,
            background: 'linear-gradient(90deg, #FF8FA3, #FFD166)',
          }}
        />
        <span
          style={{
            fontFamily: '"Noto Sans CJK SC", sans-serif',
            fontSize: 26,
            letterSpacing: '0.35em',
            color: 'rgba(255,255,255,0.85)',
          }}
        >
          你好 · 世界
        </span>
      </div>

      {/* 配音 */}
      <Sequence from={7}>
        <Audio src={staticFile('vo_s1.mp3')} />
      </Sequence>

      {/* 句级字幕 */}
      <Subtitle text="嗨，你好呀！" startFrame={7} endFrame={48} />
    </AbsoluteFill>
  );
};

import React from 'react';
import {
  AbsoluteFill,
  Audio,
  Img,
  Sequence,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';
import {Particles} from '../Particles';
import {Subtitle} from '../Subtitle';

// 场景 3 · 收束：拉远 + 标题逐字浮现，欢迎落版
const TITLE = '欢迎来到我的世界';

export const Scene3Ending: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const DURATION = 129;

  const fadeIn = interpolate(frame, [0, 10], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  // 从近景拉远，人物淡出向纯背景过渡
  const scale = interpolate(frame, [0, 55], [1.14, 1.0]);
  const imageOpacity = interpolate(frame, [40, 75], [0.9, 0.18], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const endFade = interpolate(frame, [DURATION - 14, DURATION - 2], [1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const chars = TITLE.split('');

  return (
    <AbsoluteFill style={{opacity: fadeIn * endFade}}>
      {/* 收束背景：更亮更暖的光晕 */}
      <AbsoluteFill
        style={{
          background:
            'radial-gradient(110% 90% at 50% 42%, #4A3566 0%, #2E2347 55%, #1B1530 100%)',
        }}
      />
      <AbsoluteFill
        style={{
          background:
            'radial-gradient(50% 42% at 50% 30%, rgba(255,180,150,0.24) 0%, transparent 70%)',
        }}
      />
      <AbsoluteFill
        style={{
          background:
            'radial-gradient(45% 40% at 50% 78%, rgba(126,200,227,0.16) 0%, transparent 70%)',
        }}
      />

      {/* 虚拟人拉远 */}
      <AbsoluteFill
        style={{
          transform: `scale(${scale})`,
          opacity: imageOpacity,
        }}
      >
        <Img
          src={staticFile('hero_wave.png')}
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
          }}
        />
      </AbsoluteFill>

      <Particles count={40} seed={31} opacityScale={1.15} />

      {/* WELCOME 小标 */}
      <div
        style={{
          position: 'absolute',
          top: '30%',
          left: 0,
          right: 0,
          textAlign: 'center',
          opacity: interpolate(frame, [18, 40], [0, 1], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          }),
        }}
      >
        <span
          style={{
            fontFamily: '"Noto Sans CJK SC", sans-serif',
            fontSize: 30,
            letterSpacing: '0.6em',
            color: 'rgba(255,209,102,0.92)',
            marginLeft: '0.6em',
          }}
        >
          WELCOME
        </span>
      </div>

      {/* 标题逐字浮现 */}
      <div
        style={{
          position: 'absolute',
          top: '38%',
          left: 0,
          right: 0,
          textAlign: 'center',
        }}
      >
        {chars.map((ch, i) => {
          const s = spring({
            frame: frame - 24 - i * 3,
            fps,
            config: {damping: 200, stiffness: 160, mass: 0.6},
          });
          return (
            <span
              key={i}
              style={{
                display: 'inline-block',
                fontFamily: '"Noto Serif CJK SC", "Noto Sans CJK SC", serif',
                fontWeight: 900,
                fontSize: 92,
                color: '#FFFFFF',
                letterSpacing: '0.05em',
                textShadow: '0 4px 30px rgba(255,143,163,0.35)',
                opacity: s,
                transform: `translateY(${(1 - s) * 46}px) scale(${0.9 + s * 0.1})`,
              }}
            >
              {ch}
            </span>
          );
        })}
      </div>

      {/* 底部引导小字 */}
      <div
        style={{
          position: 'absolute',
          bottom: 210,
          left: 0,
          right: 0,
          textAlign: 'center',
          opacity: interpolate(frame, [60, 84], [0, 1], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          }),
        }}
      >
        <span
          style={{
            fontFamily: '"Noto Sans CJK SC", sans-serif',
            fontSize: 30,
            letterSpacing: '0.25em',
            color: 'rgba(255,255,255,0.72)',
          }}
        >
          很高兴遇见你
        </span>
      </div>

      {/* 配音 */}
      <Sequence from={238}>
        <Audio src={staticFile('vo_s3.mp3')} />
      </Sequence>

      {/* 句级字幕 */}
      <Subtitle text="未来，让我们一起探索更多可能吧！" startFrame={238} endFrame={326} />
    </AbsoluteFill>
  );
};
